  ('923faae2-08a9-5791-85f7-c3b4f30f384a', null, (select id from public.skills where slug = 'read-g9-argument-evidence'), null, 'easy',
   $q$What evidence does the author give that noise from the market would be a small problem?$q$, $q$[{"text":"Many residents cannot visit the Saturday farmers market.","is_correct":false,"misconception_token":"mismatched-reason"},{"text":"Shop sales in Ridgeport rose by twenty percent on Fridays.","is_correct":false,"misconception_token":"mismatched-reason"},{"text":"The market would end at ten, and few homes face the square.","is_correct":true},{"text":"Vendors would pay a weekly fee of forty dollars each.","is_correct":false,"misconception_token":"mismatched-reason"}]$q$::jsonb, $q$The market would end at ten, and few homes face the square.$q$, $q$The paragraph about noise says the market ends at ten o'clock and "only two apartment buildings face the square." The vendor fee answers the cost concern, not the noise concern.$q$, 'draft', '246e0f16-a078-574b-9ec5-789814524639')
