  ('773031a3-2692-590c-a19e-131dc49e9247', null, (select id from public.skills where slug = 'read-g9-argument-evidence'), null, 'medium',
   $q$What flaw in reasoning appears in the paragraph that begins "We have a simple choice"?$q$, $q$[{"text":"It attacks the character of people who disagree with the author.","is_correct":false,"misconception_token":"misidentifies-fallacy"},{"text":"It pretends only two outcomes are possible and predicts an extreme result.","is_correct":true},{"text":"It relies on numbers from a town that is very different from Marlow.","is_correct":false,"misconception_token":"misidentifies-fallacy"},{"text":"It repeats the same evidence about sales that appeared earlier.","is_correct":false,"misconception_token":"misidentifies-fallacy"}]$q$::jsonb, $q$It pretends only two outcomes are possible and predicts an extreme result.$q$, $q$Saying the town must either host the market or "slowly die" ignores many other possibilities, and the claim that the square will be "empty forever" is an exaggerated prediction. The paragraph does not attack anyone personally.$q$, 'draft', '246e0f16-a078-574b-9ec5-789814524639')
